 let start=performance.now(),last=[-1,-1],poses=['',''];$('reviewPName').textContent=profile.name;paint($('pReviewArt'),profile.char,'idle');function summarize(s,limit,side,i){let ev=s.events.filter(e=>e.t<=limit),sum=0,cur=0,max=0,miss=0;for(let e of ev){sum+=weights[e.g];if(e.g==='miss'){cur=0;miss++}else cur++;max=Math.max(max,cur)}let partial=Math.round(13000*sum/notes.length),starsN=thresholds.filter(x=>partial>=x).length;$(side+'ReviewScore').textContent=num(partial);$(side+'ReviewStars').textContent=stars(starsN);$(side+'ReviewStats').textContent=`${miss} fallos · ${max} combo máx.`;$(side+'ReviewAcc').textContent=`${ev.length?Math.round(sum/ev.length*100):100}% precisión`;let bucket=Math.floor(limit/12);if(bucket!==last[i]){last[i]=bucket;let recent=ev.filter(e=>e.t>=limit-15);let quality=recent.length?recent.reduce((n,e)=>n+weights[e.g],0)/recent.length:1;let pose=recent.length===0?'idle':quality<.48?'miss':quality>.83?'perfect':'ready';if(pose!==poses[i]){poses[i]=pose;paint($(side+'ReviewArt'),i?other():profile.char,pose,!i);retrigger($(side+'ReviewArt'),'review-react')}$(side+'ReviewReaction').textContent=pose==='miss'?'¡A recuperar!':pose==='perfect'?'¡Gran racha!':pose==='ready'?'¡Buen ritmo!':'Preparación';}}
