$('spinGacha').onclick=()=>spin(1);$('spinTen').onclick=()=>spin(10);$('redeemBtn').onclick=()=>{if(spinBusy)return;if($('redeemInput').value.trim().toLowerCase()!=='rpmods55'){$('redeemStatus').textContent='Código incorrecto';return}profile.tickets+=10;store.set('profile',profile);syncProfile();renderGacha();$('redeemStatus').textContent='+10 tickets · código local de pruebas reutilizable';};

// Deterministic team maps. Split consecutive notes into small vocal groups, rotate 1–3 active lanes.
function splitRoutes(base,n){let routes=Array.from({length:n},()=>[]),groups=[],chunk=[],last=-99;for(let note of base){if(chunk.length&&(note.t-last>1.25||note.t-chunk[0].t>=5.2||chunk.length>=13)){groups.push(chunk);chunk=[]}chunk.push(note);last=note.t}if(chunk.length)groups.push(chunk);for(let [g,group] of groups.entries()){let width=Math.min(n,g%3===0?1:g%3===1?2:3,Math.ceil(group.length/3)),order=Array.from({length:n},(_,i)=>i).sort((a,b)=>routes[a].length-routes[b].length||((a-g%n+n)%n)-((b-g%n+n)%n)).slice(0,width);for(let [i,note] of group.entries()){let lane=order[Math.floor(i/3)%width];routes[lane].push(note)}}return routes}
function botChar(i,side){return characters[(i+side+characters.indexOf(profile.char)+1)%characters.length]}
function member(char,name,side,idx){return {char,name,side,idx,stats:fresh(),notes:[],cursor:0,el:null}}
function renderArena(){let box=$('arenaRosters');if(!box)return;box.replaceChildren();for(let side=0;side<2;side++){let col=document.createElement('div');col.className='arena-roster '+(side?'rival':'ally');for(let i=0;i<teamSize;i++){let c=!side&&i===0?profile.char:teamSize===1?other():botChar(i,side),card=document.createElement('div');card.className='roster-member';let art=document.createElement('div');art.className='roster-art';paint(art,c,'idle',!side&&i===0);let label=document.createElement('b');label.textContent=!side&&i===0?profile.name:(side?'Nova ':'Cherry ')+(i+1);card.append(art,label);col.append(card)}box.append(col)}$('teamInfo').textContent=teamSize===1?'Cada participante juega la ruta completa.':`Relevos vocales entre ${teamSize} integrantes. Solo tu carril recibe tus teclas.`;document.querySelectorAll('[data-team]').forEach(el=>el.classList.toggle('selected',+el.dataset.team===teamSize))}
$('teamModes').onclick=e=>{let el=e.target.closest('[data-team]');if(el){teamSize=+el.dataset.team;renderArena()}};
function setupTeams(){for(let id of ['pFeedback','pParticles'])document.querySelector('.player-dancer').prepend($(id));teamNotes=[];teamBots=[];teamEventList=[];botTeamCursor=0;teamCards=[];teamLastPaint=-1;let strip=$('squadStrip');document.querySelector('.stage').append(strip);strip.classList.toggle('hidden',!(mode==='versus'&&teamSize>1));$('teamTurn').classList.toggle('hidden',!(mode==='versus'&&teamSize>1));if(mode!=='versus'||teamSize===1)return;teamNotes=splitRoutes(selectedNotes(),teamSize);for(let side=0;side<2;side++){let parent=$(side?'enemyStrip':'allyStrip');parent.replaceChildren();for(let i=0;i<teamSize;i++){let c=!side&&i===0?profile.char:botChar(i,side),m=member(c,!side&&i===0?profile.name:(side?'Nova ':'Cherry ')+(i+1),side,i);m.notes=teamNotes[i];if(!side&&i===0)m.stats=p;teamBots.push(m);parent.dataset.size=teamSize;parent.style.setProperty('--slots',teamSize);let card=document.createElement('div');card.className='squad-member';card.dataset.side=side?'enemy':'ally';card.dataset.size=teamSize;let art=document.createElement('div');art.className='team-art';art.dataset.character=c;art.dataset.custom=!side&&i===0?'yes':'no';art.dataset.pose='';setPose(art,'ready');let label=document.createElement('b');label.textContent=m.name;let stat=document.createElement('small');stat.textContent='LISTO';let lane=document.createElement('div');lane.className='mini-lane';card.append(art,label,stat,lane);parent.append(card);m.el=card;m.art=art;m.label=stat;m.lane=lane;teamCards.push(m);if(!side&&i===0){card.classList.add('local-player');card.prepend($('pFeedback'),$('pParticles'));continue;}for(let [j,note] of m.notes.entries()){let seed=(Math.imul(j+1+i*71+side*311,2654435761)>>>0)/4294967296;let cut={rookie:[.24,.53,.79],standard:[.48,.81,.94],expert:[.76,.94,.99]}[botLevel];let g=seed<cut[0]?'perfect':seed<cut[1]?'great':seed<cut[2]?'good':'miss';teamEventList.push({m,note,g,at:note.t+(note.hold||0)+.025+seed*.055})}}}teamEventList.sort((a,b)=>a.at-b.at)}
