function pickSong(id){songId=id;chart=songs[id].chart;let path=songs[id].path;for(let el of document.querySelectorAll('.track-picker [data-song]'))el.classList.toggle('selected',el.dataset.song===id);document.querySelector('.trackimage img').src=path+'cover.jpg';document.querySelector('.trackimage span').textContent='♪ '+fmt(Math.round(chart.duration));document.querySelector('.trackinfo h1').textContent=chart.title;document.querySelector('.trackinfo p').textContent=chart.artist+' · Music Video';document.querySelector('.trackinfo .tag').textContent=id==='nakano'?'Ruta estimada · mezcla completa':'Voz aislada · ruta fija';$('intro').querySelector('h1').textContent=chart.title;$('intro').querySelector('p').textContent=chart.artist+' · Music Video';updateDiff();renderArena()}
