async function preloadImage(url){
 if(preloaded.some(i=>i.dataset.preloadURL===url))return true;
 const img=new Image();img.dataset.preloadURL=url;
 let timeout;
 try{
  await Promise.race([new Promise((resolve,reject)=>{img.onload=resolve;img.onerror=()=>reject(Error('image load'));img.src=url;if(img.complete&&img.naturalWidth)resolve()}),new Promise((_,reject)=>{timeout=setTimeout(()=>reject(Error('timeout')),4500)})]);
  preloaded.push(img);return true;
 }catch{return false}finally{clearTimeout(timeout);img.onload=null;img.onerror=null}
}
$('bootStart').onclick=async()=>{
 const button=$('bootStart'), overlay=$('boot');if(button.disabled)return;
 button.disabled=true;$('bootLoad').classList.remove('hidden');$('bootStatus').textContent='Preparando recursos…';$('bootProgress').value=0;
 let done=0,failed=0,closed=false,timer;
 function enter(message){if(closed)return;closed=true;clearTimeout(timer);$('bootProgress').value=100;$('bootStatus').textContent=message;overlay.classList.add('boot-done');setTimeout(()=>{overlay.classList.add('hidden');$('shell').inert=false},450)}
 $('shell').inert=true;
 // A slow or unavailable image must never trap the player at START.
 timer=setTimeout(()=>enter('Carga parcial: los recursos restantes se cargarán al usarlos.'),18000);
 try{
  let urls=[...characters.flatMap(c=>poseNames.map(p=>`assets/hd/${c}-${p}.png`)),...Object.values(songs).map(x=>x.path+'cover.jpg'),...characters.flatMap(c=>poseNames.flatMap(p=>{let temp=document.createElement('div');paint(temp,c,p,true);return [...temp.style.backgroundImage.matchAll(/url\("?([^")]+)"?\)/g)].map(m=>m[1])}))];
  urls=[...new Set(urls)];
  for(let i=0;i<urls.length;i+=8){if(closed)break;await Promise.all(urls.slice(i,i+8).map(async url=>{if(!await preloadImage(url))failed++;done++;if(!closed){$('bootProgress').value=done/urls.length*100;$('bootStatus').textContent=`Recursos ${done}/${urls.length}`}}))}
  enter(failed?`${failed} recursos no disponibles; se cargarán al usarlos.`:'¡Todo listo!');
 }catch(error){console.warn('Carga inicial parcial:',error);enter('Carga parcial. Puedes continuar al menú.')}
};
