const pages=new Map();function paginate(id,reset=false){let grid=$(id),items=[...grid.children].filter(x=>x.matches('.shop-item'));if(!items.length){document.getElementById(id+'Pager')?.remove();return}let cols=innerWidth>=1400?(id==='shopGrid'?4:3):innerWidth>=1000?3:innerWidth>=600?2:2,cap=innerWidth>=1000?(innerHeight<790?cols:cols*2):4;if(reset)pages.set(id,0);let n=Math.ceil(items.length/cap),pg=Math.min(pages.get(id)||0,n-1);pages.set(id,pg);items.forEach((el,i)=>el.hidden=i<pg*cap||i>=(pg+1)*cap);let bar=document.getElementById(id+'Pager');if(!bar){bar=document.createElement('div');bar.id=id+'Pager';bar.className='catalog-pager';grid.after(bar)}bar.replaceChildren();let prev=document.createElement('button'),next=document.createElement('button'),text=document.createElement('span');prev.className=next.className='secondary';prev.textContent='‹';next.textContent='›';text.textContent=`${pg+1} / ${n} · ${items.length} objetos`;prev.disabled=pg===0;next.disabled=pg>=n-1;prev.onclick=()=>{pages.set(id,pg-1);paginate(id)};next.onclick=()=>{pages.set(id,pg+1);paginate(id)};bar.append(prev,text,next)}
